-- name: GetInstanceSettings :one
SELECT id, registration_mode, require_email_verification, allowed_origins, password_min_length, access_token_ttl_seconds, refresh_token_ttl_seconds, refresh_idle_ttl_seconds, updated_at, updated_by FROM instance_settings WHERE id = true;

-- name: UpdateInstanceSettings :one
UPDATE instance_settings SET registration_mode = COALESCE(sqlc.narg(registration_mode), registration_mode), require_email_verification = COALESCE(sqlc.narg(require_email_verification), require_email_verification), allowed_origins = COALESCE(sqlc.narg(allowed_origins), allowed_origins), password_min_length = COALESCE(sqlc.narg(password_min_length), password_min_length), access_token_ttl_seconds = COALESCE(sqlc.narg(access_token_ttl_seconds), access_token_ttl_seconds), refresh_token_ttl_seconds = COALESCE(sqlc.narg(refresh_token_ttl_seconds), refresh_token_ttl_seconds), refresh_idle_ttl_seconds = COALESCE(sqlc.narg(refresh_idle_ttl_seconds), refresh_idle_ttl_seconds), updated_at = now(), updated_by = sqlc.narg(updated_by) WHERE id = true RETURNING id, registration_mode, require_email_verification, allowed_origins, password_min_length, access_token_ttl_seconds, refresh_token_ttl_seconds, refresh_idle_ttl_seconds, updated_at, updated_by;
